class HeteroGatherRun(val tokenBits:Int=32,val countBits:Int=16) extends Bundle {val firstToken=UInt(tokenBits.W);val tokenCount=UInt(countBits.W);val page=UInt(tokenBits.W);val last=Bool();override def cloneType:this.type=new HeteroGatherRun(tokenBits,countBits).asInstanceOf[this.type]}
class HeteroSparseGatherRunCoalescer(val tokenBits:Int=32,val countBits:Int=16) extends Module {
  val io=IO(new Bundle{val start=Input(Bool());val pageTokens=Input(UInt(countBits.W));val in=Flipped(Decoupled(new HeteroTokenItem(tokenBits)));val out=Decoupled(new HeteroGatherRun(tokenBits,countBits));val busy=Output(Bool());val done=Output(Bool())});val sIdle::sCollect::sEmit::Nil=Enum(3);val state=RegInit(sIdle);val pt=RegInit(1.U(countBits.W));val valid=RegInit(false.B);val first=Reg(UInt(tokenBits.W));val lastTok=Reg(UInt(tokenBits.W));val count=Reg(UInt(countBits.W));val finalRun=RegInit(false.B);val pending=RegInit(false.B);val pendTok=Reg(UInt(tokenBits.W));val pendLast=RegInit(false.B);val done=RegInit(false.B);val runPage=first/pt;val inPage=io.in.bits.token/pt;val cont=io.in.bits.token===lastTok+1.U&&inPage===runPage
  io.in.ready:=state===sCollect&&!pending;io.out.valid:=state===sEmit&&valid;io.out.bits.firstToken:=first;io.out.bits.tokenCount:=count;io.out.bits.page:=runPage;io.out.bits.last:=finalRun&&!pending;io.busy:=state=/=sIdle;io.done:=done;done:=false.B
  when(state===sIdle){when(io.start){pt:=Mux(io.pageTokens===0.U,1.U,io.pageTokens);valid:=false.B;pending:=false.B;state:=sCollect}}.elsewhen(state===sCollect){when(io.in.fire){when(!valid){valid:=true.B;first:=io.in.bits.token;lastTok:=io.in.bits.token;count:=1.U;finalRun:=io.in.bits.last;when(io.in.bits.last){state:=sEmit}}.elsewhen(cont){lastTok:=io.in.bits.token;count:=count+1.U;finalRun:=io.in.bits.last;when(io.in.bits.last){state:=sEmit}}.otherwise{pending:=true.B;pendTok:=io.in.bits.token;pendLast:=io.in.bits.last;finalRun:=false.B;state:=sEmit}}}.elsewhen(state===sEmit){when(io.out.fire){when(pending){first:=pendTok;lastTok:=pendTok;count:=1.U;finalRun:=pendLast;pending:=false.B;when(!pendLast){state:=sCollect}}.otherwise{valid:=false.B;state:=sIdle;done:=true.B}}}
}

class HeteroMtpTokenPair(val tokenBits:Int=20) extends Bundle {val draftToken=UInt(tokenBits.W);val targetToken=UInt(tokenBits.W);val last=Bool();override def cloneType:this.type=new HeteroMtpTokenPair(tokenBits).asInstanceOf[this.type]}
class HeteroMtpDecision(val countBits:Int=8,val domainBits:Int=16,val generationBits:Int=16) extends Bundle {val acceptedPrefix=UInt(countBits.W);val comparedTokens=UInt(countBits.W);val rollbackTokens=UInt(countBits.W);val mismatch=Bool();val commitDomainMask=UInt(domainBits.W);val rollbackDomainMask=UInt(domainBits.W);val nextGeneration=UInt(generationBits.W);override def cloneType:this.type=new HeteroMtpDecision(countBits,domainBits,generationBits).asInstanceOf[this.type]}
class HeteroMtpVerifyCommit(val tokenBits:Int=20,val maxDraftTokens:Int=16,val domainBits:Int=16,val generationBits:Int=16) extends Module {
  private val cb=math.max(1,log2Ceil(maxDraftTokens+1));val io=IO(new Bundle{val start=Input(Bool());val domainMask=Input(UInt(domainBits.W));val generation=Input(UInt(generationBits.W));val in=Flipped(Decoupled(new HeteroMtpTokenPair(tokenBits)));val out=Decoupled(new HeteroMtpDecision(cb,domainBits,generationBits));val busy=Output(Bool());val done=Output(Bool())});val sIdle::sCompare::sEmit::Nil=Enum(3);val state=RegInit(sIdle);val acc=RegInit(0.U(cb.W));val cmp=RegInit(0.U(cb.W));val mismatch=RegInit(false.B);val dm=Reg(UInt(domainBits.W));val gen=Reg(UInt(generationBits.W));val done=RegInit(false.B);io.in.ready:=state===sCompare;io.out.valid:=state===sEmit;io.out.bits.acceptedPrefix:=acc;io.out.bits.comparedTokens:=cmp;io.out.bits.rollbackTokens:=cmp-acc;io.out.bits.mismatch:=mismatch;io.out.bits.commitDomainMask:=Mux(acc=/=0.U,dm,0.U);io.out.bits.rollbackDomainMask:=Mux(mismatch,dm,0.U);io.out.bits.nextGeneration:=gen+Mux(mismatch,1.U,0.U);io.busy:=state=/=sIdle;io.done:=done;done:=false.B
  when(state===sIdle){when(io.start){acc:=0.U;cmp:=0.U;mismatch:=false.B;dm:=io.domainMask;gen:=io.generation;state:=sCompare}}.elsewhen(state===sCompare){when(io.in.fire){val equal=io.in.bits.draftToken===io.in.bits.targetToken;when(!mismatch&&equal){acc:=acc+1.U};when(!equal){mismatch:=true.B};cmp:=cmp+1.U;when(io.in.bits.last||cmp+1.U>=maxDraftTokens.U){state:=sEmit}}}.elsewhen(state===sEmit){when(io.out.fire){state:=sIdle;done:=true.B}}
}
